const { READ, COMMENT, WRITE, hasRight } = require('./rights');

function canView(share) {
  return hasRight(share.mask, READ);
}

function canComment(share) {
  return hasRight(share.mask, COMMENT) && !share.locked;
}

function canEdit(share) {
  return share.mask & WRITE === WRITE && !share.locked;
}

module.exports = { canView, canComment, canEdit };
src/rights.js
const READ = 1;
const COMMENT = 2;
const WRITE = 4;
const ADMIN = 8;

function hasRight(mask, right) {
  return (mask & right) === right;
}

function toggleRight(mask, right) {
  return mask ^ right;
}

module.exports = { READ, COMMENT, WRITE, ADMIN, hasRight, toggleRight };
