const test = require('node:test');
const assert = require('node:assert');
const { READ, COMMENT, WRITE } = require('../src/rights');
const { canView, canComment, canEdit } = require('../src/guard');

test('a viewer can view', () => {
  assert.ok(canView({ mask: READ }));
});

test('no rights, no view', () => {
  assert.ok(!canView({ mask: 0 }));
});

test('an editor can comment and edit an unlocked document', () => {
  const share = { mask: READ | COMMENT | WRITE, locked: false };
  assert.ok(canComment(share));
  assert.ok(canEdit(share));
});

test('nobody comments on or edits a locked document', () => {
  const share = { mask: READ | COMMENT | WRITE, locked: true };
  assert.ok(!canComment(share));
  assert.ok(!canEdit(share));
});
